<script setup lang="ts">
import {localFetch,readJson} from './http'
import {computed,ref,onMounted,onUnmounted} from 'vue'
import Icon from './Icon.vue'
import PeRiver from './PeRiver.vue'
import MarketMa20 from './MarketMa20.vue'
import type {Ma20Data} from './MarketMa20.vue'
import FearGauge from './FearGauge.vue'
import MarketFlowTrend from './MarketFlowTrend.vue'
import MarketValueTrend from './MarketValueTrend.vue'
import FedRateChart from './FedRateChart.vue'
import BondSpreads from './BondSpreads.vue'
import type {CreditData} from './BondSpreads.vue'
import type {FedRateData,RateStep} from './rateChart'
import type {ValueReading,FlowReading} from './marketComparison'
import {quoteComparison} from './marketComparison'
import {normalizeMarketOrder,moveCard} from './marketLayout'
type PositionRow={name:string;long:number;short:number;net:number}
type PositionDay={date:string;rows:PositionRow[]}
type Item={title:string;url:string;published_at?:string}
type RiskSample={count:number;declines:number;rate_pct:number|null;range_95_pct:[number,number]|null}
type RiskHorizon={key:string;label:string;definition:string;value:number|null;sample:RiskSample|null;baseline:RiskSample;at_least65:RiskSample;at_least70:RiskSample;elevated:boolean}
type Data={source_date?:string;history?:ValueReading[]|FlowReading[]|PositionDay[]|RateStep[];previous_bid?:number|null;previous_ask?:number|null;as_of:string|null;note:string;items?:Item[];rows?:any[];value?:number|null;change_pct?:number|null;unit?:string;symbol?:string;bid?:number;ask?:number;rating?:string;low?:number;high?:number;next_start?:string;next_end?:string;calendar_url?:string;retail_long?:number;retail_short?:number;average_20?:number|null;ratio?:number|null;readiness?:string;score?:number|null;sample?:RiskSample|null;baseline?:RiskSample;at_least65?:RiskSample;at_least70?:RiskSample;elevated?:boolean;elevated_horizons?:string[];horizons?:RiskHorizon[];score70_reached?:boolean|null;decision_at?:string;rule?:string}
type Card={id:string;title:string;kind:string;source:string;url:string;data:Data|null;saved_at:string|null;checked_at:string|null;error:string}
type Report={cards:Card[];job:{running:boolean;done:number;total:number;message:string}}
const report=ref<Report|null>(null),error=ref(''),editing=ref(false),order=ref<string[]>([]),dragging=ref(''),over=ref(''),layoutNotice=ref(''),starting=ref(false)
let timer:ReturnType<typeof setTimeout>|undefined,alive=true,epoch=0
const storageKey='branch-monitor.market-layout.v1'
const running=computed(()=>starting.value||report.value?.job.running)
const cards=computed(()=>order.value.map(id=>report.value?.cards.find(c=>c.id===id)).filter((c):c is Card=>!!c))
const available=computed(()=>report.value?.cards.filter(c=>c.data).length||0)
const fmt=(v:number|null|undefined,d=0)=>v==null?'—':v.toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d})
const signed=(v:number|null|undefined,d=2)=>v==null?'—':(v>0?'+':'')+fmt(v,d)
const tone=(n:number|undefined|null)=>n==null||n===0?'muted':n>0?'positive':'negative'
const timestamp=(s:string|null|undefined)=>s?s.replace('T',' ').replace(/([+-]\d{2}:\d{2}|Z)$/,'').slice(0,19):'—'
const priceDigits=(id:string)=>id==='twd'?3:id==='jpy'?3:2
const quoteMove=(data:Data)=>quoteComparison(data.history as ValueReading[]||[],data.source_date||data.as_of?.slice(0,10)||'',data.value,data.change_pct)
const positionHistory=(data:Data,name:string):ValueReading[]=>(data.history as PositionDay[]||[]).flatMap(day=>{const row=day.rows.find(r=>r.name===name);return row?[{date:day.date,value:row.net}]:[]})
const previousPosition=(data:Data,name:string)=>{const previous=(data.history as PositionDay[]||[]).filter(d=>d.date<(data.source_date||data.as_of||'')).sort((a,b)=>a.date.localeCompare(b.date)).at(-1);return previous?.rows.find(r=>r.name===name)}
const sentiment=(v:number|null|undefined)=>v==null?'等待來源':v<25?'極度恐懼':v<45?'恐懼':v<=55?'中性':v<=75?'貪婪':'極度貪婪'
function saveOrder(){try{localStorage.setItem(storageKey,JSON.stringify(order.value));layoutNotice.value='排列已儲存在此瀏覽器'}catch{layoutNotice.value='此瀏覽器無法儲存排列，目前僅保留本次調整'}}
function move(id:string,step:number){const i=order.value.indexOf(id),target=order.value[i+step];if(target){order.value=moveCard(order.value,id,target);saveOrder()}}
function drag(event:DragEvent,id:string){if(!editing.value)return;dragging.value=id;event.dataTransfer?.setData('text/plain',id);if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
function drop(target:string){if(editing.value&&dragging.value){order.value=moveCard(order.value,dragging.value,target);saveOrder()}dragging.value='';over.value=''}
function reset(){order.value=report.value?.cards.map(c=>c.id)||[];saveOrder()}
async function load(){
 const id=++epoch;clearTimeout(timer)
 try{const response=await localFetch('/api/market-monitor');const data=await readJson(response);if(!alive||id!==epoch)return;if(!response.ok)throw new Error(data.error||'無法讀取市場觀測');report.value=data;error.value='';const ids=data.cards.map((c:Card)=>c.id)
  if(!order.value.length){let saved:unknown=null;try{saved=JSON.parse(localStorage.getItem(storageKey)||'null')}catch{}order.value=normalizeMarketOrder(saved,ids)}else order.value=normalizeMarketOrder(order.value,ids)
  if(data.job.running)timer=setTimeout(()=>{void load()},2000)
 }catch(e){if(alive&&id===epoch){error.value=(e as Error).message;timer=setTimeout(()=>{void load()},10000)}}
}
async function refresh(card?:string){starting.value=true;try{const r=await localFetch('/api/market-monitor/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(card?{card}:{})});const value=await readJson(r);if(!r.ok)throw new Error(value.error||'無法更新市場資料');await load()}catch(e){error.value=(e as Error).message}finally{starting.value=false}}
onMounted(()=>{void load()});onUnmounted(()=>{alive=false;epoch++;clearTimeout(timer)})
</script>
<template>
 <div class="market-observation">
  <header class="page-header"><div><div class="eyebrow">MARKET OBSERVATORY</div><h1>市場觀測</h1><p>新聞、資金與全球市場，放在同一個視野。</p></div><div class="market-actions"><button class="market-layout-button" :aria-pressed="editing" @click="editing=!editing">{{editing?'完成排列':'調整排列'}}</button><button class="primary" :disabled="running" @click="refresh()"><Icon name="refresh" :size="17" :class="{spinning:running}"/>{{running?'市場資料更新中':'更新市場資料'}}</button></div></header>
  <div class="market-summary"><span><i :class="{busy:running}"></i>{{running?`更新 ${report?.job.done||0} / ${report?.job.total||13} 張卡片`:`已保存 ${available} / ${report?.cards.length||13} 張卡片`}}</span><span>切換頁籤沿用本機資料 · 按更新才重新讀取來源</span></div>
  <div v-if="error" class="error-banner" role="alert">{{error}}<button @click="load">重新讀取</button></div>
  <div v-if="editing" class="market-layout-hint"><Icon name="grid" :size="18"/><span>拖曳卡片標題調整位置，或使用 ← → 按鈕。排列會自動保存。</span><button @click="reset">恢復預設</button></div>
  <p class="market-layout-status" aria-live="polite">{{layoutNotice}}</p>
  <p v-if="!report" class="watch-loading">正在讀取已保存的市場資料…</p>
  <section class="market-grid" aria-label="市場觀測儀表板">
   <article v-for="(card,index) in cards" :key="card.id" class="market-card" :class="[{wide:card.kind==='futures'||card.kind==='rates'||card.kind==='v6_outlook',editable:editing,dragging:dragging===card.id,'drop-target':over===card.id},'kind-'+card.kind]" :data-card="card.id" @dragover.prevent="editing&&(over=card.id)" @drop.prevent="drop(card.id)">
    <header class="market-card-heading" :draggable="editing" @dragstart="drag($event,card.id)" @dragend="dragging='';over=''">
     <div><span class="market-card-kicker">{{card.kind==='ma20'?'DUAL INDEX · SMA20 DISTANCE':card.kind==='credit'?'CORPORATE CREDIT · USD / EUR':card.kind==='pe_river'?'PRICE & TURNOVER RIVER':card.kind==='news'?'HEADLINES · TOP 5':card.kind==='institution'?'INSTITUTIONAL FLOWS':card.kind==='quote'?'MARKET PRICE':card.kind==='rates'?'MONETARY POLICY':card.kind==='fear'?'MARKET SENTIMENT':card.kind==='v6_outlook'?'NEXT-SESSION DOWNSIDE':card.kind==='retail'?'RETAIL POSITIONING':card.kind==='volume'?'MARKET TURNOVER':'FUTURES POSITIONING'}}</span><h2><span v-if="editing" class="market-grip" aria-hidden="true">⠿</span>{{card.title}}</h2></div>
     <div class="market-card-controls"><template v-if="editing"><button :disabled="index===0" :aria-label="card.title+'往前移'" @click="move(card.id,-1)">←</button><button :disabled="index===cards.length-1" :aria-label="card.title+'往後移'" @click="move(card.id,1)">→</button></template><button v-else :aria-label="'更新'+card.title" :disabled="running" @click="refresh(card.id)"><Icon name="refresh" :size="15"/></button></div>
    </header>
    <div v-if="card.error" class="market-card-warning" role="status">{{card.kind==='credit'&&card.data?'部分債券資料待補，逐檔標示。':card.kind==='pe_river'&&card.data?'部分資料待補。':card.data?'更新失敗，保留上次資料。':'暫無可用數據。'}}{{card.error}}</div>
    <div v-if="!card.data" class="market-card-empty"><span class="market-empty-value">—</span><p>{{card.error?'可開啟原始來源查看，或稍後重試。':'首次使用請按「更新市場資料」。'}}</p><a :href="card.url" target="_blank" rel="noopener noreferrer">開啟 {{card.source}} ↗</a></div>
    <template v-else>
     <PeRiver v-if="card.kind==='pe_river'" :data="card.data as any" embedded/>
     <MarketMa20 v-else-if="card.kind==='ma20'" :data="card.data as unknown as Ma20Data"/>
     <ol v-else-if="card.kind==='news'" class="market-headlines"><li v-for="(item,i) in card.data.items" :key="item.url"><span class="market-news-number">{{String(i+1).padStart(2,'0')}}</span><div><a :href="item.url" :title="item.title" target="_blank" rel="noopener noreferrer">{{item.title}}</a><small v-if="item.published_at">{{timestamp(item.published_at)}}</small></div><span aria-hidden="true">↗</span></li></ol>
     <div v-else-if="card.kind==='institution'" class="market-flows"><div v-for="row in card.data.rows" :key="row.name"><span>{{row.name}}</span><strong :class="tone(row.net)">{{signed(row.net/1e8)}}<small> 億</small></strong><div class="market-flow-details"><span>買進 {{fmt((row.buy||0)/1e8,2)}} 億</span><span>賣出 {{fmt((row.sell||0)/1e8,2)}} 億</span></div><MarketFlowTrend :name="row.name" :net="row.net" :date="card.data.source_date||card.data.as_of||''" :history="card.data.history as FlowReading[]|undefined"/></div></div>
     <div v-else-if="card.kind==='futures'" class="market-table-scroll"><table class="market-futures-table"><thead><tr><th>身分</th><th>多單</th><th>空單</th><th>多空淨額</th></tr></thead><tbody><tr v-for="row in card.data.rows" :key="row.name"><td>{{row.name}}</td><td>{{fmt(row.long)}}<small v-if="previousPosition(card.data,row.name)">前 {{fmt(previousPosition(card.data,row.name)!.long)}} · {{signed(row.long-previousPosition(card.data,row.name)!.long,0)}}</small></td><td>{{fmt(row.short)}}<small v-if="previousPosition(card.data,row.name)">前 {{fmt(previousPosition(card.data,row.name)!.short)}} · {{signed(row.short-previousPosition(card.data,row.name)!.short,0)}}</small></td><td :class="tone(row.net)">{{signed(row.net,0)}}<small v-if="previousPosition(card.data,row.name)">前 {{signed(previousPosition(card.data,row.name)!.net,0)}} · {{signed(row.net-previousPosition(card.data,row.name)!.net,0)}}</small></td></tr></tbody></table><small class="market-unit">單位：口 · 台股期貨</small></div>
     <FedRateChart v-else-if="card.kind==='rates'" :data="card.data as FedRateData"/>
     <BondSpreads v-else-if="card.kind==='credit'" :data="card.data as unknown as CreditData"/>
     <FearGauge v-else-if="card.kind==='fear'" :value="card.data.value" :date="card.data.source_date||card.data.as_of?.slice(0,10)||''" :history="card.data.history as ValueReading[]|undefined"/>
     <div v-else-if="card.kind==='v6_outlook'" class="market-outlook"><span>未來 1～5 個交易日與下週 K · 歷史相似日</span><div class="market-outlook-value"><strong>{{card.data.readiness==='ready'&&card.data.value!=null?fmt(card.data.value,1)+'%':'—'}}</strong><b>{{card.data.readiness==='ready'?(card.data.elevated_horizons?.length?'有區間出現偏高條件':'各區間未達偏高門檻'):card.data.readiness==='waiting'?'等待 08:30 隔夜資料':'資料未齊'}}</b></div><div class="market-outlook-bar"><i :style="{width:(card.data.value||0)+'%'}"></i></div><p>上方為 1 個交易日參考率 · V6 風險分數 {{card.data.score==null?'—':fmt(card.data.score,1)}}／100</p><div class="market-outlook-table"><table><thead><tr><th>區間</th><th>65 分以上</th><th>70 分以上</th><th>整體基準</th></tr></thead><tbody><tr v-for="h in card.data.horizons||[]" :key="h.key"><td>{{h.label}}<small v-if="h.elevated">條件偏高</small></td><td>{{fmt(h.at_least65.rate_pct,1)}}%<small>{{h.at_least65.declines}}／{{h.at_least65.count}}{{h.at_least65.count<30?' · 樣本少':''}}</small></td><td>{{fmt(h.at_least70.rate_pct,1)}}%<small>{{h.at_least70.declines}}／{{h.at_least70.count}} · 樣本少</small></td><td>{{fmt(h.baseline.rate_pct,1)}}%<small>{{h.baseline.declines}}／{{h.baseline.count}}</small></td></tr></tbody></table></div><p v-if="card.data.sample">1 日當前分數組 {{card.data.sample.declines}}／{{card.data.sample.count}} 次收跌 · 95% 近似區間 {{fmt(card.data.sample.range_95_pct?.[0],0)}}–{{fmt(card.data.sample.range_95_pct?.[1],0)}}%</p><p class="market-outlook-rule">{{card.data.rule}} 下週 K 以該週收盤低於開盤計算。</p></div>
     <div v-else-if="card.kind==='retail'" class="market-indicator"><span>散戶多空比</span><strong :class="tone(card.data.value)">{{signed(card.data.value,2)}}<small>%</small></strong><div><span>散戶做多 {{fmt(card.data.retail_long,0)}}</span><span>散戶做空 {{fmt(card.data.retail_short,0)}}</span></div><p>正值偏多、負值偏空；風控採反向解讀。</p></div>
     <div v-else-if="card.kind==='volume'" class="market-indicator"><span>上市成交金額</span><strong>{{fmt(card.data.value,0)}}<small> 億</small></strong><div><span>近 20 日均值 {{fmt(card.data.average_20||undefined,0)}} 億</span><span>量能比 {{card.data.ratio==null?'—':fmt(card.data.ratio,2)+'×'}}</span></div></div>
     <div v-else class="market-quote"><span class="market-symbol">{{card.data.symbol}}</span><strong>{{fmt(card.data.value,priceDigits(card.id))}}</strong><div class="market-quote-sub"><span>{{card.data.unit}}</span><b v-if="quoteMove(card.data).value!=null" :class="tone(quoteMove(card.data).value)">{{quoteMove(card.data).label}} {{signed(quoteMove(card.data).value)}}%</b></div><div v-if="card.id==='gold'" class="market-gold-spread"><span>造市商買 {{fmt(card.data.bid,0)}}</span><span>賣 {{fmt(card.data.ask,0)}}</span></div></div>
     <div v-if="['quote','retail','volume'].includes(card.kind)" class="market-history"><MarketValueTrend :value="card.data.value" :date="card.data.source_date||card.data.as_of?.slice(0,10)||''" :history="card.data.history as ValueReading[]|undefined" :unit="card.kind==='volume'?'億元':card.data.unit||''" :intraday="card.kind==='quote'" :digits="card.kind==='quote'?priceDigits(card.id):undefined" :label="card.title"/><p v-if="card.id==='gold'&&card.data.previous_bid!=null" class="gold-previous">來源前日造市商買／賣 {{fmt(card.data.previous_bid)}}／{{fmt(card.data.previous_ask)}} 元／台錢<br>買價增減 {{signed((card.data.bid||0)-card.data.previous_bid)}} 元 · 賣價增減 {{signed((card.data.ask||0)-(card.data.previous_ask||0))}} 元</p></div>
     <div v-if="card.kind==='futures'" class="position-history"><article v-for="row in card.data.rows" :key="row.name"><h3>{{row.name}} · 淨部位</h3><MarketValueTrend :value="row.net" :date="card.data.source_date||card.data.as_of||''" :history="positionHistory(card.data,row.name)" unit="口" :label="row.name" zero-line/></article></div>
     <p v-if="!['pe_river','ma20'].includes(card.kind)" class="market-card-note">{{card.kind==='quote'&&card.id!=='gold'?'來源最新報價，可能延遲；較前值百分比與下方增減均以標示的同一前值計算。':card.data.note}}</p>
    </template>
    <footer class="market-card-footer"><div><span v-if="card.data?.as_of">資料 {{timestamp(card.data.as_of)}}</span><span v-else-if="card.saved_at">擷取 {{timestamp(card.saved_at)}}</span><span v-else>尚未取得</span><small v-if="card.checked_at">檢查 {{timestamp(card.checked_at)}}</small></div><a :href="card.url" target="_blank" rel="noopener noreferrer">{{card.source}} ↗</a></footer>
   </article>
  </section>
  <p class="market-page-note">各卡片使用來源各自的資料日期；盤後法人資料與盤中報價不一定同日。台幣／日圓數值上升代表每美元可兌換更多當地貨幣；原油為布蘭特期貨報價。時間含時分者顯示台北時間，FOMC 會議日期依美東。</p>
 </div>
</template>
<style scoped>
